// Tokyo: list stays in the desk; New and opening a record use the Books editor,
// which fills accounts, amounts and taxes (the plain desk form cannot).
(function () {
  const BOOKS = "/books/edit/SalesInvoice/";
  const settings = (frappe.listview_settings["Books Sales Invoice"] = frappe.listview_settings["Books Sales Invoice"] || {});
  settings.primary_action = () => { window.location.href = BOOKS + "new"; };
  settings.get_form_link = (doc) => BOOKS + encodeURIComponent(doc.name);
})();

